#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
python3 -m unittest discover -v -s tests -p 'test_*.py'
if command -v kotlinc >/dev/null 2>&1 && command -v kotlin >/dev/null 2>&1; then
  TEMP_DIR="$(mktemp -d)"; trap 'rm -rf "$TEMP_DIR"' EXIT
  kotlinc app/src/main/java/dev/caicompanion/app/{HostBlocker,LoginCompatibility,UrlPolicy,FilterEngine,BoundedText,BrowserProfile,SafeFilename,DownloadPolicy,RuleListParser,IncomingLinkParser,BrowserSessionPolicy,RendererRecoveryBudget,SupportReport,NativeLibrarySearch,NativeWorkspaceNavigation,NativeStartupPolicy,DeferredWebReload,OfflineBookmarkEditor,DeviceCompatibility,GeckoNavigationPolicy,GeckoTransferPolicy,GeckoTransferOriginPolicy,ExternalBrowserPolicy,VoiceDraftPolicy,VoiceRecognitionGuard,VoiceRecognitionFeedback}.kt \
    app/src/main/java/dev/caicompanion/app/VoiceComposerPolicy.kt app/src/main/java/dev/caicompanion/app/ReleasePolicy.kt tests/ReleasePolicySmoke.kt app/src/main/java/dev/caicompanion/app/UpdateIntegrity.kt tests/UpdateIntegritySmoke.kt app/src/main/java/dev/caicompanion/app/UpdateProgress.kt tests/UpdateProgressSmoke.kt app/src/main/java/dev/caicompanion/app/VoiceRecognitionOptions.kt tests/VoiceRecognitionOptionsSmoke.kt app/src/main/java/dev/caicompanion/app/VoiceAlternatives.kt tests/VoiceAlternativesSmoke.kt app/src/main/java/dev/caicompanion/app/DeviceRuntimeCapabilities.kt tests/DeviceRuntimeCapabilitiesSmoke.kt app/src/main/java/dev/caicompanion/app/LorebookPolicy.kt app/src/main/java/dev/caicompanion/app/LorebookEditor.kt tests/LorebookEditorSmoke.kt app/src/main/java/dev/caicompanion/app/LorebookDraftCodec.kt tests/LorebookDraftSmoke.kt tests/LorebookSmoke.kt app/src/main/java/dev/caicompanion/app/PngLorebookCard.kt tests/PngLorebookSmoke.kt app/src/main/java/dev/caicompanion/app/CharacterDraftPolicy.kt app/src/main/java/dev/caicompanion/app/CharacterDraftCodec.kt tests/CharacterDraftSmoke.kt app/src/main/java/dev/caicompanion/app/CharacterDraftExtras.kt tests/CharacterExtrasSmoke.kt app/src/main/java/dev/caicompanion/app/CharacterDraftBackup.kt tests/BackupSmoke.kt app/src/main/java/dev/caicompanion/app/CharxCard.kt tests/CharxSmoke.kt tests/BrowserRestoreSmoke.kt tests/LoginRouteSmoke.kt tests/FilterImportSmoke.kt app/src/main/java/dev/caicompanion/app/ServiceLoadFeedback.kt tests/ServiceLoadSmoke.kt app/src/main/java/dev/caicompanion/app/RoleplayToolkit.kt tests/RoleplayToolkitSmoke.kt app/src/main/java/dev/caicompanion/app/ChatRefreshPolicy.kt tests/ChatRefreshSmoke.kt tests/PolicySmoke.kt -d "$TEMP_DIR/policy.jar"
  kotlin -classpath "$TEMP_DIR/policy.jar" PolicySmokeKt
else
  echo 'Kotlin toolchain unavailable: skipped pure Kotlin tests' >&2
fi
